import java.io.*;
import java.nio.charset.StandardCharsets;

public class Main {
    public static void main(String[] args) throws IOException {
        String[] z = new String(System.in.readAllBytes(), StandardCharsets.UTF_8).split("\r?\n", -1);
        int q = Integer.parseInt(z[0].trim());
        int p = 1;
        StringBuilder out = new StringBuilder();
        for (int t = 0; t < q; t++) {
            String[] header = z[p].trim().split("\\s+");
            long la = Long.parseLong(header[0]), lb = Long.parseLong(header[1]);
            String a = z[p + 1], b = z[p + 2];
            p += 3;
            if (a.equals("-")) a = "";
            if (b.equals("-")) b = "";
            if (la != lb) {
                out.append("-1\n");
                continue;
            }
            int[] ca = new int[26], cb = new int[26];
            for (int i = 0; i < a.length(); i++) ca[a.charAt(i) - 'a']++;
            for (int i = 0; i < b.length(); i++) cb[b.charAt(i) - 'a']++;
            long diff = 0;
            for (int i = 0; i < 26; i++) diff += Math.abs(ca[i] - cb[i]);
            out.append(diff / 2).append('\n');
        }
        System.out.print(out);
    }
}

package main

import (
	"bufio"
	"io"
	"os"
	"strconv"
	"strings"
)

func main() {
	raw, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	z := strings.Split(string(raw), "\n")
	for i := range z {
		z[i] = strings.TrimSuffix(z[i], "\r")
	}
	q, _ := strconv.Atoi(strings.TrimSpace(z[0]))
	p := 1
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	for t := 0; t < q; t++ {
		header := strings.Fields(z[p])
		a, b := z[p+1], z[p+2]
		p += 3
		if a == "-" {
			a = ""
		}
		if b == "-" {
			b = ""
		}
		la, _ := strconv.Atoi(header[0])
		lb, _ := strconv.Atoi(header[1])
		if la != lb {
			w.WriteString("-1\n")
			continue
		}
		var ca, cb [26]int
		for i := 0; i < len(a); i++ {
			ca[a[i]-'a']++
		}
		for i := 0; i < len(b); i++ {
			cb[b[i]-'a']++
		}
		diff := 0
		for i := 0; i < 26; i++ {
			if ca[i] > cb[i] {
				diff += ca[i] - cb[i]
			} else {
				diff += cb[i] - ca[i]
			}
		}
		w.WriteString(strconv.Itoa(diff/2) + "\n")
	}
}
